class EphemeralKVStore(Elasticsearch):

    def __init__(self, shards=1):
        super().__init__()

        self.set_shards(shards)

    def set_shards(self, shards):
        try:
            shard_responses = {}

            for shard in range(1, shards+1):
                shard_responses[shard] = self.shard_request(shard)

            self.shard_responses = shard_responses

        except Exception as e:
            self.status = 500
            return str(e)

    def write(self, key, value):
        current_time = time()

        while True:
            success = self.write_to_shard(key, value)

            if success >= INFLIGHT_MSGS:
                return

            current_time += 1

            if current_time >= max(self.shard_responses.get(1), self.shard_responses.get(2)):
                return

        return

    def write_to_shard(self, key, value):
        success = 0

        for i in range(1, 3):
            try:
                if self.post('/data'+i, json={'key':key, 'value':value}).status_code == 200:
                    success += 1

            except:
                continue

        return success

    def read(self, key):
        value = None

        for i in range(1, 3):
            try:
                res = self.get('/data'+i, params={'query':key}).json()

                value = res['result']['value']

                break

            except:
                continue

        return value

